    for (const x of all) (x.st.s === 'ready' ? g.ready : x.st.s === 'done' ? g.done : x.st.s === 'locked' ? g.locked : x.st.s === 'off' ? g.off : g.later).push(x);
    g.later.sort((a, b) => (a.st.next || 9e15) - (b.st.next || 9e15));
