  const poundSeenGet = () => { try { const v = JSON.parse(sessionStorage.getItem('bnp-poundseen') || '[]'); return Array.isArray(v) ? v.filter((x) => x && /^[\w-]{1,20}$/.test(String(x.n || ''))) : []; } catch (_) { return []; } };
