    for (const li of $$('#boardList li[data-topic]')) li.classList.toggle('bnp-nb-out', (!!q && !goNorm(`${(li.querySelector('.boardTopicTitle > a') || {}).textContent || ''} ${li.dataset.author}`).includes(q)) || !nbFltOf(li, k, marks, me));
