    const navH = () => { const n = $('#navtop__2020'); return n ? Math.max(0, n.getBoundingClientRect().bottom) : 0; };
    bar.style.visibility = 'hidden';   // (its height, out of sight: a post jumped to stops just under it, with a little room)
    bar.hidden = false;
    document.documentElement.style.setProperty('--nb-jumpgap', `${Math.round(navH() + 8 + bar.offsetHeight + 14)}px`);
    bar.hidden = true;
    bar.style.visibility = '';
