  let nfLoad = null;   // ({ on, list, n: read, got: found, why: why it stopped, wait: 'tab' | 'away' | '' }: while it goes, and after)
  const NF_EACH = 11;   // (seconds a lookup takes, on average, with its pauses: for the time it says it'll take)
