      let doc = nmDoc(await r.text());
      if (!doc.querySelector('form[name="messages"]')) doc = nmDoc(await (await fetch(location.href, { credentials: 'include' })).text());
      if (!nmSwap(tc, doc)) throw new Error('no list came back');
