    const a = e.target.closest('[data-g="nmtabs"] a[href], .bnp-nmsub a[href], a.bnp-nmrange[href]');
    if (!a || (a.target && a.target !== '_self') || a.hasAttribute('download') || !nmSame(a.href) || nmFull().includes(nmKind(a.href))) return;
