      if (kind === 'every') { c.hours = Number(v('hours')) || 1; c.start = Date.now() + c.hours * 3600000; }
      if (kind === 'once') { c.at = new Date(v('at')).getTime(); if (!(c.at > Date.now())) { toast('Pick a time that’s still to come'); return; } }
