      <div class="bnp-avcard-main"><div class="bnp-avcard-head"><b>${esc(a.n)}</b><span class="bnp-note">${esc(avKinds(a))}</span>${avState(a)}</div>
        <div class="bnp-avhow">${a.h ? avTidy(a.h) : '<i>SunnyNeo has no words on this one yet.</i>'}</div>
        <div class="bnp-avacts">${avActs(a)}</div></div>
