    if ((k === 'up' || k === 'down') && i >= 0) { const j = i + (k === 'up' ? -1 : 1); if (j < 0 || j >= T.rules.length) return; [T.rules[i], T.rules[j]] = [T.rules[j], T.rules[i]]; tabsChanged(); return; }
